style.css:
/* The Moonlit Wood - Global */
/* i really want this to be global */

:root {
  /* Puedes cambiar estos colores */
  --my-bg: #101719;
  --my-surface: #1b2529;
  --my-text: #c7a9ed;
  --my-muted: #a98bd3;
  --my-purple: #b58be8;
  --my-lavender: #d5bafa;
  --my-deep: #7952a8;
  --my-silver: #c6d0d1;
}

/* fondo nocturno */
body {
  background-color: var(--my-bg) !important;
  background-image:
    radial-gradient(ellipse at 50% 0%, #35464b 0%, transparent 55%),
    linear-gradient(180deg, #101719, #151e22) !important;
  color: var(--my-text) !important;
  font-family: "Hiragino Maru Gothic", "Hiragino Maru Gothic ProN", sans-serif !important;
}

/* tipografía general */
h1, h2, h3, h4, h5, h6,
p, span, label, li, td, th,
div, a, button, input, textarea, select {
  font-family: "Hiragino Maru Gothic", "Hiragino Maru Gothic ProN", sans-serif !important;
  color: var(--my-text) !important;
}

/* títulos */
h1, h2, h3, h4, h5, h6 {
  color: var(--my-lavender) !important;
}

/* enlaces */
a {
  color: var(--my-purple) !important;
  transition: color 0.2s ease !important;
}

a:hover {
  color: var(--my-lavender) !important;
}

/* superficies */
header, nav, aside, section, article {
  border-color: #526164 !important;
}

/* botones */
button {
  background: var(--my-surface) !important;
  color: var(--my-lavender) !important;
  border: 1px solid var(--my-deep) !important;
  border-radius: 8px !important;
}

/* campos de texto */
input, textarea, select {
  background: #182225 !important;
  color: var(--my-lavender) !important;
  border: 1px solid var(--my-deep) !important;
  border-radius: 7px !important;
}

/* imágenes */
img {
  border-radius: 5px !important;
}
